-- #584 10-15 VERIFIER: the reader's PROPOSED predicate_sql, verbatim as it would sit in the YAML (folded scalar = one line, no comments), at 100M, then the same text at 50M.
BEGIN READ ONLY;
\echo === Z3a: proposed predicate at 100M (threshold 15)
SELECT COUNT(DISTINCT ticker) FROM ( WITH cal AS ( SELECT trade_date, (row_number() OVER (ORDER BY trade_date))::int rn FROM (SELECT DISTINCT trade_date FROM mi_daily_closes WHERE trade_date >= (SELECT MIN(scan_date) FROM mi_universe_floor_shadow)) x ) SELECT s.ticker FROM mi_universe_floor_shadow s JOIN cal c0 ON c0.trade_date = s.scan_date JOIN cal c20 ON c20.rn = c0.rn + 20 JOIN LATERAL ( SELECT count(*) FILTER (WHERE w.trade_date > s.scan_date) n_fwd, max(w.q) maxq, max(w.close) FILTER (WHERE w.trade_date = c20.trade_date) c20 FROM (SELECT d.trade_date, d.close, d.close / NULLIF(lag(d.close) OVER (ORDER BY d.trade_date), 0) q FROM mi_daily_closes d WHERE d.ticker = s.ticker AND d.trade_date BETWEEN s.scan_date AND c20.trade_date) w) f ON true WHERE (s.failed_price_floor OR s.failed_volume_floor) AND s.minutes_since_open_at_open <= 15 AND s.today_dollar_volume_at_open >= 100000000 AND f.c20 IS NOT NULL AND f.n_fwd = 20 AND COALESCE(f.maxq, 0) <= 4 AND (SELECT count(*) FROM (SELECT 1 FROM mi_daily_closes d WHERE d.ticker = s.ticker AND d.trade_date < s.scan_date ORDER BY d.trade_date DESC LIMIT 20) z) = 20 ) t;
\echo === Z3b: same text at 50M
SELECT COUNT(DISTINCT ticker) FROM ( WITH cal AS ( SELECT trade_date, (row_number() OVER (ORDER BY trade_date))::int rn FROM (SELECT DISTINCT trade_date FROM mi_daily_closes WHERE trade_date >= (SELECT MIN(scan_date) FROM mi_universe_floor_shadow)) x ) SELECT s.ticker FROM mi_universe_floor_shadow s JOIN cal c0 ON c0.trade_date = s.scan_date JOIN cal c20 ON c20.rn = c0.rn + 20 JOIN LATERAL ( SELECT count(*) FILTER (WHERE w.trade_date > s.scan_date) n_fwd, max(w.q) maxq, max(w.close) FILTER (WHERE w.trade_date = c20.trade_date) c20 FROM (SELECT d.trade_date, d.close, d.close / NULLIF(lag(d.close) OVER (ORDER BY d.trade_date), 0) q FROM mi_daily_closes d WHERE d.ticker = s.ticker AND d.trade_date BETWEEN s.scan_date AND c20.trade_date) w) f ON true WHERE (s.failed_price_floor OR s.failed_volume_floor) AND s.minutes_since_open_at_open <= 15 AND s.today_dollar_volume_at_open >= 50000000 AND f.c20 IS NOT NULL AND f.n_fwd = 20 AND COALESCE(f.maxq, 0) <= 4 AND (SELECT count(*) FROM (SELECT 1 FROM mi_daily_closes d WHERE d.ticker = s.ticker AND d.trade_date < s.scan_date ORDER BY d.trade_date DESC LIMIT 20) z) = 20 ) t;
\echo === Z3c: the 100M in-window rejected clearers by D0 (to project when the 15th name can settle)
SELECT scan_date, count(DISTINCT ticker) n, string_agg(ticker, ',' ORDER BY ticker) tickers FROM mi_universe_floor_shadow
WHERE (failed_price_floor OR failed_volume_floor) AND minutes_since_open_at_open <= 15 AND today_dollar_volume_at_open >= 100000000 AND scan_date <= DATE '2026-10-14'
GROUP BY 1 ORDER BY 1;
ROLLBACK;
